{
  "document_type": "lease",
  "lessor": "Ankara Teknoloji Gelistirme Bölgesi Kurucu ve Isletici Anonim Sirketi (Ankara Cyberpark)",
  "lessee": "Synplicity Arastirma Gelistirme Ltd. Sti.",
  "premises_address": "Cyberplaza A Blok 3.Kat No: A308, Bilkent/ANKARA",
  "area": null,
  "start_date": "2005-08-15",
  "end_date": "2007-08-15",
  "rent": {
    "amount": 2442,
    "currency": "TRY",
    "period": "month"
  },
  "indexation": "none",
  "red_flags": [
    {
      "type": "tenant_break_option",
      "quote": "Lessee shall not hire leasehold to third parties as well as shall not leave leasehold to third parties for these latter to avail themselves of its use without seeking approval for in writing from Ankara Cyberpark."
    },
    {
      "type": "tenant_break_option",
      "quote": "Practice to the contrary shall be left to the discretion and approval in writing of Ankara Cyberpark. Lessee is not entitled to make any statement or to take on any obligation as to putting a personal or in kind limitation whatsoever on leasehold."
    },
    {
      "type": "tenant_break_option",
      "quote": "Lessee cannot displace, convey, carry fixtures mentioned in Annex-1 to hereby Contract and parts and pieces of leasehold to any other place outside of location described as freehold site and cannot displace the same without seeking approval in writing of Ankara Cyberpark."
    },
    {
      "type": "tenant_break_option",
      "quote": "In the event Lessee, by acting at variance with the provisions of hereby lease Contract or even if by not so doing, causes insurance risk to enhance as a result of faulty doings, attitudes, behaviors done and taken by itself and/or causes Ankara Cyberpark to remain outside of indemnification clauses of insurance policies, and declines from making known this fact to Ankara Cyberpark, it shall accept, consent to and undertake to pay immediately all insurance premiums to ensure continuance of insurance indemnification as soon as this fact is becomes known to insurance company as a result of information to be provided by Ankara Cyberpark."
    },
    {
      "type": "tenant_break_option",
      "quote": "In the event a loss and damage makes itself manifest within the scope of insurance indemnification and Ankara Cyberpark does make no bid to terminate contract in accordance with provisions of Clause 36 herein under, insurance indemnification recovered from insurance company shall be allocated to removal of damage arisen or to its full substitution. However, in the course of such allocation, owing to risks falling outside of insurance coverage and/or owing to costs incurred in excess of insurance coverage, onus of all payments to be made shall lie with Lessee."
    },
    {
      "type": "tenant_break_option",
      "quote": "In the event Lessee defaults in making payment of rent in accordance with the provisions of the Annex-1 to hereby Contract and fails to make payment of rent, together with default interest to accrue on the basis of the Clause 33 of hereby Contract, within a term of 30 days to be granted within the frame of hereby Contract by Ankara Cyberpark, this latter shall be entitled to immediately terminate hereby Contract."
    },
    {
      "type": "tenant_break_option",
      "quote": "On Lessee defaulting repeatedly within a term of six months to pay rents in accordance with the provisions of Annex-1 of hereby Contract, then Ankara Cyberpark shall be authorized to terminate contract at once."
    },
    {
      "type": "tenant_break_option",
      "quote": "In the event Lessee defaults in making payment of rent in accordance with the provisions of the Annex-1 to hereby Contract and fails to make payment of rent, together with default interest to accrue on the basis of the Clause 33 of hereby Contract, within a term of 30 days to be granted within the frame of hereby Contract by Ankara Cyberpark, this latter shall be entitled to immediately terminate hereby Contract."
    }
  ]
}
